#define NVD (sizeof(VDS) / sizeof(VDS[0]))

static void test_verify_data(void) {
    TEST_SUITE("tls_finished_verify_data — cross-checked against cryptography.HMAC");
    for (size_t i = 0; i < NVD; i++) {
        uint8_t out[32];
        tls_finished_verify_data(VDS[i].finished_key, VDS[i].transcript_hash, out);
        ASSERT_TRUE("verify_data matches", memcmp(out, VDS[i].expected, 32) == 0);
    }
}

static void test_transcript_dependence(void) {
    TEST_SUITE("tls_finished_verify_data — depends on the transcript hash");
    uint8_t out1[32], th2[32];
    tls_finished_verify_data(VDS[0].finished_key, VDS[0].transcript_hash, out1);
    memcpy(th2, VDS[0].transcript_hash, 32);
    th2[0] ^= 0xff;
    uint8_t out2[32];
    tls_finished_verify_data(VDS[0].finished_key, th2, out2);
    int same = memcmp(out1, out2, 32) == 0;
    ASSERT_EQ("different transcript hash changes verify_data", 0, same);
}

int main(void) {
    test_verify_data();
    test_transcript_dependence();
    test_summary();
    return 0;
}
